// When mouse is pressed, trigger() saves the explosion center and time
    // update() moves each particle outward with speed, delay, sparkle, and fading
    // display() draws each particle as a glowing, sparkling star that fades out

    {
      // When the firework was triggered
      triggered: -1000000,
      // How long the animation lasts (ms)
      duration: 1400,
      // Where the firework explodes
      centerX: 0,
      centerY: 0,
      // How many particles in the firework
      particleCount: 28,
      // Array to store each particle's info
      particles: [],
      // Save the mouse position and time when triggered
      trigger: function(objects, x, y) {
        // Save the explosion center
        this.centerX = x;
        this.centerY = y;
        // Save when the firework started
        this.triggered = millis();
        // Clear old particles
        this.particles = [];
        // Set color mode to HSB for pretty colors
        colorMode(HSB, 360, 100, 100, 255);
        // Make each particle
        for (let i = 0; i < this.particleCount; i++) {
          // Angle for this particle (evenly around the circle)
          let angle = (TWO_PI * i) / this.particleCount;
          // How fast the particle moves (random between 2 and 5)
          let speed = random(2, 5);
          // How much the particle slows down each frame
          let drag = random(0.95, 0.98);
          // How long to wait before showing this particle (random delay in ms)
          let delay = random(0, 200);
          // Color hue for this particle (spread over rainbow)
          let hue = random(0, 360);
          // Store all the info for this particle
          this.particles.push({
            angle: angle,
            speed: speed,
            drag: drag,
            delay: delay,
            x: 0,
            y: 0,
            // Used to fade out the particle
            alpha: 255,
            // Used for sparkle size
            sparkleSize: random(3, 6),
            // Used for sparkle brightness
            sparkleBright: random(80, 100),
            // Particle color
            hue: hue,
            // How old is this particle (ms)
            age: 0,
            // Is this particle visible yet?
            visible: false
          });
        }
      },
      // Update all particles (no shared data needed)
      update: function(objects) {
        // How much time since the firework started
        let now = millis();
        let elapsed = now - this.triggered;
        // For each particle
        for (let i = 0; i < this.particles.length; i++) {
          let p = this.particles[i];
          // Wait for the delay before showing the particle
          if (!p.visible && elapsed > p.delay) {
            p.visible = true;
            // Start the age counter
            p.age = elapsed - p.delay;
          }
          // Only update if visible
          if (p.visible) {
            // Move the particle outward
            p.x += cos(p.angle) * p.speed;
            p.y += sin(p.angle) * p.speed;
            // Slow down the particle
            p.speed *= p.drag;
            // Add some random jitter for sparkle
            p.x += random(-0.7, 0.7);
            p.y += random(-0.7, 0.7);
            // Age the particle
            p.age += deltaTime;
            // Fade out the alpha (slower at first, faster at end)
            let fadeStart = this.duration * 0.5;
            if (elapsed > fadeStart + p.delay) {
              let fadeAmount = map(elapsed - fadeStart - p.delay, 0, this.duration * 0.5, 0, 255);
              p.alpha = max(0, 255 - fadeAmount);
            }
            // Sparkle: randomly change brightness and size a little
            p.sparkleBright += random(-5, 5);
            p.sparkleBright = constrain(p.sparkleBright, 70, 100);
            p.sparkleSize += random(-0.4, 0.4);
            p.sparkleSize = constrain(p.sparkleSize, 2, 7);
          }
        }
      },
      // Draw all particles
      display: function() {
        // Set color mode for glowing colors
        colorMode(HSB, 360, 100, 100, 255);
        // Draw each particle
        for (let i = 0; i < this.particles.length; i++) {
          let p = this.particles[i];
          // Only draw if visible and not fully faded
          if (p.visible && p.alpha > 0) {
            // Make the glow by drawing several circles with different alpha and size
            push();
            // Move to the explosion center plus particle offset
            translate(this.centerX + p.x, this.centerY + p.y);
            noStroke();
            // Outer glow (bigger, more transparent)
            fill(p.hue, 80, 100, p.alpha * 0.12);
            ellipse(0, 0, p.sparkleSize * 4, p.sparkleSize * 4);
            // Middle glow
            fill(p.hue, 90, p.sparkleBright, p.alpha * 0.25);
            ellipse(0, 0, p.sparkleSize * 2.2, p.sparkleSize * 2.2);
            // Inner star (brightest)
            fill(p.hue, 100, 100, p.alpha);
            // Draw a little star shape
            this.drawStar(0, 0, p.sparkleSize * 0.5, p.sparkleSize, 5);
            pop();
          }
        }
      },
      // Helper to draw a star shape at (x, y)
      drawStar: function(x, y, radius1, radius2, npoints) {
        // Star has points sticking out
        let angle = TWO_PI / npoints;
        let halfAngle = angle / 2.0;
        beginShape();
        for (let a = 0; a < TWO_PI; a += angle) {
          let sx = x + cos(a) * radius2;
          let sy = y + sin(a) * radius2;
          vertex(sx, sy);
          sx = x + cos(a + halfAngle) * radius1;
          sy = y + sin(a + halfAngle) * radius1;
          vertex(sx, sy);
        }
        endShape(CLOSE);
      }
    }

// On mouse press, pick a random ingredient type and color.
// Save the mouse position and start a falling animation from above.
// Ingredient falls down until it reaches the surface.
// On impact, create a ripple, spawn larger fragments that fly outward and fade.
// Random bubbles rise and fade from the impact area.
// All elements disappear after the animation duration.

{
  // Timestamp of last trigger (ms)
  triggered: -1000000,
  // Animation duration (ms)
  duration: 2200,

  // Drop position and fall parameters
  dropX: 0,
  dropY: 0,
  startZ: -90,
  surfaceZ: 0,
  fallSpeed: 0.22,
  atSurface: false,
  impactTime: -1,

  // Ingredient properties
  ingredientType: 0,
  ingredientColor: [0,0,0],

  // Fragment properties
  fragmentCount: 0,
  fragments: [],

  // Ripple properties
  rippleRadius: 0,
  rippleAlpha: 0,

  // Bubble properties
  bubbles: [],
  lastBubbleTime: 0,

  // Pick a random ingredient type and color
  pickIngredient: function() {
    this.ingredientType = floor(random(3));
    colorMode(HSB, 360, 100, 100, 255);
    let hue = random(360);
    if (this.ingredientType === 0) this.ingredientColor = [hue, 80, 90, 255];
    else if (this.ingredientType === 1) this.ingredientColor = [hue, 60, 80, 255];
    else this.ingredientColor = [hue, 100, 60, 255];
    this.fragmentCount = floor(random(3,8));
  },

  // Trigger the animation at the mouse position
  trigger: function(objects, x, y) {
    this.dropX = x;
    this.dropY = y;
    this.startZ = -90;
    this.atSurface = false;
    this.impactTime = -1;
    this.pickIngredient();
    this.fragments = [];
    this.rippleRadius = 0;
    this.rippleAlpha = 0;
    this.bubbles = [];
    this.lastBubbleTime = millis();
    this.triggered = millis();
    if (!("triggerCounter" in varContainer)) varContainer.triggerCounter = 0;
    varContainer.triggerCounter++;
  },

  // Update the animation state
  update: function(objects) {
    let t = millis() - this.triggered;
    if (t < 0 || t > this.duration) return;

    // Falling phase
    if (!this.atSurface) {
      let z = this.startZ + this.fallSpeed * t * 1.5;
      if (z >= this.surfaceZ) {
        z = this.surfaceZ;
        this.atSurface = true;
        this.impactTime = millis();
        this.fragments = [];
        let angleStep = TWO_PI/this.fragmentCount;
        // Create fragments with outward velocities
        for (let i=0; i<this.fragmentCount; i++) {
          let ang = angleStep*i + random(-0.3,0.3);
          let speed = random(1.2,2.5);
          this.fragments.push({
            x: this.dropX,
            y: this.dropY,
            vx: cos(ang)*speed,
            vy: sin(ang)*speed,
            alpha: 255,
            t0: millis()
          });
        }
        this.rippleRadius = 0;
        this.rippleAlpha = 140;
      }
      this.currentZ = z;
    } else {
      // Impact and fragment phase
      let fragTime = millis() - this.impactTime;
      for (let f of this.fragments) {
        f.x += f.vx;
        f.y += f.vy;
        f.alpha = map(fragTime, 0, 600, 255, 0, true);
      }
      this.rippleRadius = map(fragTime, 0, 700, 0, 90, true);
      this.rippleAlpha = map(fragTime, 0, 700, 140, 0, true);
    }

    // Bubble generation and update
    let now = millis();
    if (now - this.lastBubbleTime > random(90,210) && t < this.duration-300) {
      let theta = random(TWO_PI);
      let rad = random(10, 70);
      let bx = this.dropX + cos(theta)*rad;
      let by = this.dropY + sin(theta)*rad;
      let bsize = random(7,16);
      this.bubbles.push({
        x: bx,
        y: by,
        r: bsize,
        alpha: 180,
        t0: now
      });
      this.lastBubbleTime = now;
    }
    for (let b of this.bubbles) {
      let bt = now - b.t0;
      b.y -= 0.13;
      b.alpha = map(bt, 0, 900, 180, 0, true);
    }
    this.bubbles = this.bubbles.filter(b => b.alpha > 8);
  },

  // Draw the animation
  display: function() {
    let t = millis() - this.triggered;
    if (t < 0 || t > this.duration) return;
    colorMode(HSB, 360, 100, 100, 255);
    noStroke();

    // Draw bubbles
    for (let b of this.bubbles) {
      fill(185, 30, 100, b.alpha);
      ellipse(b.x, b.y, b.r, b.r);
    }

    // Draw ripple
    if (this.atSurface && this.rippleAlpha > 3) {
      noFill();
      stroke(180, 16, 100, this.rippleAlpha);
      strokeWeight(4);
      ellipse(this.dropX, this.dropY, this.rippleRadius*2, this.rippleRadius*2);
      strokeWeight(1);
    }

    // Draw falling ingredient or fragments
    if (!this.atSurface) {
      push();
      translate(this.dropX, this.dropY);
      fill(0, 40);
      ellipse(0, 0, 32*2, 9*2); // shadow (double size)
      translate(0, this.currentZ);
      this.drawIngredientShape();
      pop();
    } else {
      for (let f of this.fragments) {
        push();
        translate(f.x, f.y);
        this.drawFragmentShape(f.alpha);
        pop();
      }
    }
  },

  // Draw the main ingredient shape (all sizes doubled)
  drawIngredientShape: function() {
    colorMode(HSB, 360, 100, 100, 255);
    stroke(0,0,100,255);
    strokeWeight(2.5);
    fill(this.ingredientColor[0], this.ingredientColor[1], this.ingredientColor[2], 255);
    if (this.ingredientType === 0) {
      // star (double size)
      this.drawStar(0,0,8*2,18*2,5);
    } else if (this.ingredientType === 1) {
      // blob (double size)
      ellipse(0,0,26*2,26*2);
      fill(this.ingredientColor[0], this.ingredientColor[1], this.ingredientColor[2]+18, 120);
      noStroke();
      ellipse(4*2,-6*2,7*2,7*2);
    } else {
      // crystal (double size)
      beginShape();
      vertex(0,-16*2);
      vertex(9*2,0);
      vertex(0,16*2);
      vertex(-9*2,0);
      endShape(CLOSE);
      fill(0,0,100,45);
      noStroke();
      ellipse(0,4*2,10*2,4*2);
    }
    strokeWeight(1);
    noStroke();
  },

  // Draw a star shape
  drawStar: function(x, y, radius1, radius2, npoints) {
    let angle = TWO_PI / npoints;
    let halfAngle = angle / 2.0;
    beginShape();
    for (let a = 0; a < TWO_PI; a += angle) {
      let sx = x + cos(a) * radius2;
      let sy = y + sin(a) * radius2;
      vertex(sx, sy);
      sx = x + cos(a + halfAngle) * radius1;
      sy = y + sin(a + halfAngle) * radius1;
      vertex(sx, sy);
    }
    endShape(CLOSE);
  },

  // Draw a fragment shape (all sizes doubled)
  drawFragmentShape: function(alpha) {
    colorMode(HSB, 360, 100, 100, 255);
    stroke(0,0,100,alpha);
    strokeWeight(1.2);
    fill(this.ingredientColor[0], this.ingredientColor[1], this.ingredientColor[2], alpha);
    if (this.ingredientType === 0) {
      ellipse(0,0,7*2,7*2);
    } else if (this.ingredientType === 1) {
      ellipse(0,0,6*2,9*2);
    } else {
      beginShape();
      vertex(0,-7*2);
      vertex(4*2,0);
      vertex(0,7*2);
      vertex(-4*2,0);
      endShape(CLOSE);
    }
    strokeWeight(1);
    noStroke();
  }
}

// - Fishes are automatically generated at random positions on startup.
// - trigger() sets the mouse target for all fish to follow when pressed.
// - update() always animates fish; fish follow mouse only when pressed and inside canvas.
// - Fish swim and wiggle even if mouse isn't pressed.

{
  triggered: -1000000,
  duration: 4000,
  fishCount: 8,
  fishes: [],
  mouseTarget: { x: 0, y: 0 },
  initialized: false,
  // Set the target position for fish to follow when mouse is pressed
  trigger: function(objects, x, y) {
    this.triggered = millis();
    this.mouseTarget.x = x;
    this.mouseTarget.y = y;
  },
  update: function(objects) {
    let now = millis();
    // Initialize fishes at random positions and velocities on first run
    if (!this.initialized) {
      this.fishes = [];
      for (let i = 0; i < this.fishCount; i++) {
        let fx = random(width);
        let fy = random(height);
        let vx = random(-1, 1) * 0.5;
        let vy = random(-1, 1) * 0.5;
        let phase = random(TWO_PI);
        this.fishes.push({
          x: fx,
          y: fy,
          vx: vx,
          vy: vy,
          phase: phase
        });
      }
      this.initialized = true;
    }
    // Check if mouse is pressed and inside the canvas
    let mouseInCanvas = mouseX >= 0 && mouseX < width && mouseY >= 0 && mouseY < height;
    let followMouse = mouseIsPressed && mouseInCanvas;
    if (followMouse) {
      this.mouseTarget.x = mouseX;
      this.mouseTarget.y = mouseY;
    }
    // Update each fish's position, velocity, and phase
    for (let i = 0; i < this.fishes.length; i++) {
      let fish = this.fishes[i];
      // Steer toward mouse if needed
      if (followMouse) {
        let dx = this.mouseTarget.x - fish.x;
        let dy = this.mouseTarget.y - fish.y;
        let distToTarget = sqrt(dx * dx + dy * dy);
        let dirX = distToTarget > 1 ? dx / distToTarget : 0;
        let dirY = distToTarget > 1 ? dy / distToTarget : 0;
        fish.vx = fish.vx * 0.92 + dirX * 0.12;
        fish.vy = fish.vy * 0.92 + dirY * 0.12;
      }
      // Add wiggle to velocity for natural swim
      let wiggleStrength = 0.25;
      let wiggleAngle = fish.phase + now * 0.005 + i;
      fish.vx += cos(wiggleAngle) * wiggleStrength * 0.04;
      fish.vy += sin(wiggleAngle) * wiggleStrength * 0.04;
      // Move fish by velocity
      fish.x += fish.vx;
      fish.y += fish.vy;
      // Keep fish inside canvas bounds
      if (fish.x < 0) fish.x = 0;
      if (fish.x > width) fish.x = width;
      if (fish.y < 0) fish.y = 0;
      if (fish.y > height) fish.y = height;
      // Update phase for animation
      fish.phase += 0.07 + random(-0.01, 0.01);
    }
  },
  display: function() {
    let now = millis();
    colorMode(HSB, 360, 100, 100, 100);
    // Draw each fish with animated tail and eye
    for (let i = 0; i < this.fishes.length; i++) {
      let fish = this.fishes[i];
      let angle = atan2(fish.vy, fish.vx);
      let hue = (180 + i * 40) % 360;
      push();
      translate(fish.x, fish.y);
      rotate(angle);
      noStroke();
      fill(hue, 70, 90, 100); // Body color
      ellipse(0, 0, 32, 14);
      let tailWiggle = sin(fish.phase + now * 0.01) * 6;
      fill(hue, 60, 70, 90); // Tail color
      triangle(-16, 0, -28, -8 + tailWiggle, -28, 8 + tailWiggle);
      fill(0, 0, 100, 100); // Eye white
      ellipse(9, -3, 5, 5);
      fill(0, 0, 0, 100); // Eye black
      ellipse(10, -3, 2, 2);
      pop();
    }
  }
}

{  // On trigger, butterfly and palette/randomization; on update, state transitions for caterpillar, cocoon, butterfly emergence, and flight; on display, rendering logic for each stage, ensuring spots overlap wings and palettes are non-green.
  triggered: -1000000,
  duration: 11000,
  x: 0,
  y: 0,
  butterflyLift: 0,
  wingFlap: 0,
  chrysalisColor: [120, 200, 80],
  crackGlow: 0,
  wingOpen: 0,
  hasFlown: false,
  caterpillarSegments: 7,
  wingSeeds: [],
  wingPalette: {
    main: [210, 80, 90],
    spot: [210, 40, 100]
  },
  wingPalettes: [
    { main: [210, 80, 90], spot: [210, 40, 100] },
    { main: [30, 90, 95], spot: [40, 50, 100] },
    { main: [275, 60, 85], spot: [290, 30, 100] }
  ],
  caterpillarSquirmDir: 1,
  caterpillarMoveDir: 1,
  caterpillarOffset: 0,
  butterflyFlyVelX: 0,
  butterflyFlyVelY: 0,
  cocoonFade: 1,
  butterflyFlyStartX: 0,
  butterflyFlyStartY: 0,
  butterflyFlying: false,
  trigger: function(objects, x, y) {
    this.x = x;
    this.y = y;
    this.triggered = millis();
    this.butterflyLift = 0;
    this.wingFlap = 0;
    this.wingOpen = 0;
    this.hasFlown = false;
    this.cocoonFade = 1;
    this.butterflyFlying = false;
    this.butterflyFlyStartX = x;
    this.butterflyFlyStartY = y;
    let p = floor(random(this.wingPalettes.length));
    this.wingPalette = this.wingPalettes[p];
    this.wingSeeds = [];
    for (let i = 0; i < 6; i++) {
      let h = this.wingPalette.main[0] + random(-15, 15);
      let s = this.wingPalette.main[1] + random(-10, 10);
      let b = this.wingPalette.main[2] + random(-10, 10);
      this.wingSeeds.push({
        x: random(-32, 32),
        y: random(-24, 24),
        r: random(8, 18),
        h: (h + 360) % 360,
        s: constrain(s, 40, 100),
        b: constrain(b, 60, 100)
      });
    }
    this.caterpillarSquirmDir = random([1, -1]);
    this.caterpillarMoveDir = random([1, -1]);
    this.caterpillarOffset = 0;
    // Set random butterfly flight direction and speed
    let angle = random(-PI/4, -3*PI/4); // fly generally up and away
    let speed = random(2.5, 4.5);
    this.butterflyFlyVelX = cos(angle) * speed;
    this.butterflyFlyVelY = sin(angle) * speed;
  },
  update: function(objects) {
    let t = (millis() - this.triggered) / this.duration;
    t = constrain(t, 0, 1);
    if (t < 0.13) {
      this.wingOpen = 0;
      this.butterflyLift = 0;
      // Move caterpillar left or right slowly during its stage
      // Offset is a smooth function of t, direction, and a little squirm
      let dist = 60; // max pixels to move
      let squirm = sin(t * PI * 6) * 8;
      this.caterpillarOffset = map(t, 0, 0.13, 0, dist * this.caterpillarMoveDir) + squirm;
      this.cocoonFade = 1;
      this.butterflyFlying = false;
      this.x = this.butterflyFlyStartX;
      this.y = this.butterflyFlyStartY;
    }
    else if (t < 0.24) {
      let p = map(t, 0.13, 0.24, 0, 1);
      this.chrysalisColor = [
        lerp(120, 70, p),
        lerp(200, 150, p),
        lerp(80, 60, p)
      ];
      this.cocoonFade = 1;
      this.butterflyFlying = false;
      this.x = this.butterflyFlyStartX;
      this.y = this.butterflyFlyStartY;
    }
    else if (t < 0.30) {
      this.cocoonFade = 1;
      this.butterflyFlying = false;
      this.x = this.butterflyFlyStartX;
      this.y = this.butterflyFlyStartY;
      // Do nothing during this waiting phase
    }
    else if (t < 0.40) {
      let p = map(t, 0.30, 0.40, 0, 1);
      this.crackGlow = sin(PI * p);
      this.cocoonFade = 1;
      this.butterflyFlying = false;
      this.x = this.butterflyFlyStartX;
      this.y = this.butterflyFlyStartY;
    }
    else if (t < 0.65) {
      this.wingOpen = t < 0.51 ? map(t, 0.40, 0.51, 0, 1) : 1;
      this.wingFlap = t < 0.51 ? 0 : sin((millis() - this.triggered - 5100) * 0.008) * 0.25;
      // Fade cocoon out between 0.51 and 0.65
      if (t < 0.51) {
        this.cocoonFade = 1;
      } else {
        this.cocoonFade = map(t, 0.51, 0.65, 1, 0);
      }
      this.butterflyFlying = false;
      this.x = this.butterflyFlyStartX;
      this.y = this.butterflyFlyStartY;
    }
    else if (t < 1.0) {
      this.wingOpen = 1;
      this.hasFlown = true;
      this.wingFlap = sin((millis() - this.triggered - 6500) * 0.012) * 0.35;
      this.butterflyLift = map(t, 0.65, 0.78, 0, 1);
      this.cocoonFade = 0;
      // Butterfly begins to fly away after 0.78
      if (t >= 0.78) {
        if (!this.butterflyFlying) {
          this.butterflyFlying = true;
          // Save current position as flight origin if not already set
          this.x = this.butterflyFlyStartX;
          this.y = this.butterflyFlyStartY - 28 - 80 * 1; // lifted
        }
        // Move butterfly by velocity
        this.x += this.butterflyFlyVelX;
        this.y += this.butterflyFlyVelY;
        // End animation early if butterfly is off screen
        if (
          this.x < -120 || this.x > width + 120 ||
          this.y < -120 || this.y > height + 120
        ) {
          this.triggered = -1000000;
        }
      } else {
        // Stay at spot, with lift
        this.x = this.butterflyFlyStartX;
        this.y = this.butterflyFlyStartY - 28 - 80 * this.butterflyLift;
      }
    }
  },
  display: function() {
    colorMode(HSB, 360, 100, 100, 1);
    let t = (millis() - this.triggered) / this.duration;
    t = constrain(t, 0, 1);
    let cx = this.x;
    let cy = this.y;
    if (t < 0.13) {
      let curl = map(t, 0, 0.13, 0, PI * 0.9) * this.caterpillarSquirmDir;
      let faceAlpha = map(t, 0, 0.13, 1, 0.1);
      for (let i = 0; i < this.caterpillarSegments; i++) {
        let ang = curl * (i / (this.caterpillarSegments - 1));
        let segX = cx + this.caterpillarOffset + cos(ang) * (i * 22 - 66);
        let segY = cy - sin(ang) * (i * 8);
        fill(120, 80, 70, 1);
        noStroke();
        ellipse(segX, segY, 36, 28);
        if (i === 0) {
          fill(120, 90, 55, faceAlpha);
          ellipse(segX, segY, 38, 30);
          fill(0, 0, 0, faceAlpha);
          ellipse(segX - 8, segY - 6, 5, 5);
          ellipse(segX + 8, segY - 6, 5, 5);
          noFill();
          stroke(0, 0, 0, faceAlpha);
          strokeWeight(2);
          arc(segX, segY + 4, 14, 8, 0, PI);
          stroke(120, 90, 55, faceAlpha);
          strokeWeight(2);
          line(segX - 10, segY - 14, segX - 18, segY - 26);
          line(segX + 10, segY - 14, segX + 18, segY - 26);
        }
        stroke(120, 60, 30, 0.7);
        strokeWeight(3);
        let legY = segY + 16;
        line(segX - 8, legY, segX - 18, legY + 8);
        line(segX + 8, legY, segX + 18, legY + 8);
      }
    }
    // Draw chrysalis/cocoon if not fully faded
    if (t >= 0.13 && this.cocoonFade > 0.01) {
      let cc = this.chrysalisColor;
      let ovalW = 48;
      let ovalH = 70;
      let cocoonAlpha = this.cocoonFade;
      fill(cc[0], cc[1], cc[2], cocoonAlpha);
      stroke(cc[0] - 10, cc[1], cc[2] - 20, 0.5 * cocoonAlpha);
      strokeWeight(3);
      ellipse(cx, cy - 10, ovalW, ovalH);
      stroke(cc[0] - 15, cc[1] - 30, cc[2] - 15, 0.2 * cocoonAlpha);
      strokeWeight(1);
      for (let i = -2; i <= 2; i++) {
        let y = cy - 10 + i * 10;
        arc(cx, y, ovalW - 8, 18, PI, 0);
      }
      // Crack glow if in correct stage
      if (t > 0.30 && t < 0.51) {
        let glow = this.crackGlow;
        stroke(60, 10, 100, (0.5 + 0.5 * glow) * cocoonAlpha);
        strokeWeight(2 + 3 * glow);
        let crackCount = 3;
        for (let i = 0; i < crackCount; i++) {
          let ang = map(i, 0, crackCount - 1, -PI / 4, PI / 4);
          let x1 = cx + cos(ang) * 14;
          let y1 = cy - 28 + sin(ang) * 8;
          let x2 = cx + cos(ang) * 18;
          let y2 = cy - 4 + sin(ang) * 12;
          line(x1, y1, x2, y2);
        }
        noStroke();
        fill(60, 10, 100, 0.15 * glow * cocoonAlpha);
        ellipse(cx, cy - 18, 36 + 24 * glow, 28 + 18 * glow);
      }
      // Face in cocoon if in correct stage
      if (t >= 0.13 && t < 0.24) {
        let faceAlpha = map(t, 0.13, 0.24, 0.8, 0) * cocoonAlpha;
        if (faceAlpha > 0.05) {
          fill(120, 90, 55, faceAlpha);
          ellipse(cx, cy + 14, 22, 16);
        }
      }
    }
    if (t >= 0.40) {
      // Butterfly emerges and stays at cocoon spot, with wings opening/flapping, or flies away
      let drawY;
      if (this.butterflyFlying) {
        drawY = cy;
      } else {
        drawY = cy;
      }
      fill(35, 60, 40, 1);
      stroke(30, 50, 30, 1);
      strokeWeight(3);
      rect(cx - 5, drawY, 10, 48, 8);
      stroke(35, 60, 40, 1);
      strokeWeight(2);
      let antLen = t < 0.65 ? (18 + 8 * this.wingOpen) : 26;
      line(cx, drawY, cx - 10, drawY - antLen);
      line(cx, drawY, cx + 10, drawY - antLen);
      this.drawWings(cx, drawY + (t < 0.65 ? 18 : 24), this.wingOpen, this.wingFlap, this.wingSeeds);
    }
    colorMode(RGB, 255, 255, 255, 1);
  },
  drawWings: function(cx, cy, open, flap, seeds) {
    push();
    translate(cx, cy);
    // Left wing
    push();
    let leftAngle = -PI / 2 + open * PI / 3 + flap;
    rotate(leftAngle);
    this.drawWingShape(-1, open, flap, seeds);
    pop();
    // Right wing
    push();
    let rightAngle = PI / 2 - open * PI / 3 - flap;
    rotate(rightAngle);
    this.drawWingShape(1, open, flap, seeds);
    pop();
    pop();
  },
  drawWingShape: function(side, open, flap, seeds) {
    let main = this.wingPalette.main;
    let spot = this.wingPalette.spot;
    noStroke();
    // Top (larger) oval
    push();
    rotate(radians(-18 * side));
    fill(main[0], main[1], main[2], 1);
    beginShape();
    vertex(0, 0);
    bezierVertex(42 * side, -22, 68 * side, -56, 32 * side, -94 * open);
    bezierVertex(8 * side, -110 * open, -18 * side, -56, -14 * side, -12);
    endShape(CLOSE);
    pop();
    // Bottom (smaller) oval, now follows the top oval's open/flap but with smaller degree
    let bottomOpen = open * 0.8;
    let bottomFlap = flap * 0.8;
    push();
    rotate(radians(22 * side));
    fill(main[0], main[1], main[2], 1);
    beginShape();
    vertex(0, 0);
    bezierVertex(30 * side, 10, 50 * side, 34, 22 * side, 54 * bottomOpen + 12 * bottomFlap);
    bezierVertex(6 * side, 62 * bottomOpen + 16 * bottomFlap, -12 * side, 34, -8 * side, 6);
    endShape(CLOSE);
    pop();
    // Draw spots fully overlapping the wings (on top of both ovals)
    for (let i = 0; i < seeds.length; i++) {
      let s = seeds[i];
      // Spots distributed within the bounding box of the wing shapes
      let wx = s.x * side * open * 0.85;
      let wy = s.y * open * 0.85;
      fill(s.h, s.s, s.b, 0.8);
      ellipse(wx, wy, s.r, s.r * 0.7);
      if (i % 2 === 0) {
        fill(spot[0], spot[1], spot[2], 0.3);
        ellipse(wx + 4 * side, wy - 2, s.r * 0.5, s.r * 0.3);
      }
    }
    // Draw outlines for both ovals for clarity
    noFill();
    stroke(0, 0, 0, 0.4);
    strokeWeight(2);
    // Top oval outline
    push();
    rotate(radians(-18 * side));
    beginShape();
    vertex(0, 0);
    bezierVertex(42 * side, -22, 68 * side, -56, 32 * side, -94 * open);
    bezierVertex(8 * side, -110 * open, -18 * side, -56, -14 * side, -12);
    endShape();
    pop();
    // Bottom oval outline
    push();
    rotate(radians(22 * side));
    beginShape();
    vertex(0, 0);
    bezierVertex(30 * side, 10, 50 * side, 34, 22 * side, 54 * bottomOpen + 12 * bottomFlap);
    bezierVertex(6 * side, 62 * bottomOpen + 16 * bottomFlap, -12 * side, 34, -8 * side, 6);
    endShape();
    pop();
  }
}

{
  /*
    Key changes:
    - Leaves are placed along each sampled vine path.
    - Each vine position randomly sprouts a pair of leaves, a left leaf, or a right leaf.
    - When the flower opens, the leaves detach and drift with their own
      velocity, rotation, size, and fading lifetime.
    - The effect now finishes only after both petals and leaves disappear.

    Programme:
    on trigger:
      save the interaction position -> reset the vine and flower
      -> choose the stem shape -> sample the stem path
      -> place paired, left, or right leaves along the path

    on update:
      count other active objects -> grow the vine
      -> open the flower -> release drifting petals and leaves
      -> move and fade detached pieces -> finish

    on display:
      draw the revealed stem -> draw visible vine leaves
      -> draw the opening flower -> draw fading petals and leaves

    Leaves remain attached while the stem grows. When the flower pops,
    they drift away independently while rotating and fading.
  */
  triggered: -1000000,
  duration: 10000,

  // These values remember the vine, flower, falling petals, and drifting leaves.
  startX: 0,
  startY: 0,
  growTime: 2600,
  bloomTime: 850,
  vineLength: 130,
  vineCount: 18,
  pathSteps: 80,
  turnEvery: 4,
  directionX: 0,
  directionY: 0,
  curveAmount: 0,
  control1X: 0,
  control1Y: 0,
  control2X: 0,
  control2Y: 0,
  vineProgress: 0,
  bloomProgress: 0,
  phase: "idle",
  vineX: [],
  vineY: [],
  petals: [],
  leaves: [],
  leafCount: 10,
  leafMode: "pair",
  leafSideCount: 1,
  petalColors: [],
  otherCount: 0,
  age: 0,
  now: 0,
  i: 0,
  j: 0,
  segment: 0,
  segmentPart: 0,
  drawX: 0,
  drawY: 0,
  bezier1X: 0,
  bezier1Y: 0,
  bezier2X: 0,
  bezier2Y: 0,
  bezierEndX: 0,
  bezierEndY: 0,
  flowerX: 0,
  flowerY: 0,
  pathT: 0,
  multiBend: false,
  bendDirection: 1,
  bendAmount: 0,

  // This makes a smooth fast start and a soft slow finish.
  easeOut: function (value) {
    return 1 - Math.pow(1 - value, 3);
  },

  // This starts a new vine at the place that was clicked or touched.
  trigger: function (objects, x, y) {
    colorMode(RGB, 255, 255, 255, 255);

    // Make the shared click counter only once.
    if (!("triggerCounter" in varContainer)) varContainer.triggerCounter = 0;

    // Count this new click for all effect objects.
    varContainer.triggerCounter += 1;

    // Save the click position and reset the animation.
    this.triggered = millis();
    this.startX = x;
    this.startY = y;
    this.age = 0;
    this.phase = "grow";
    this.vineProgress = 0;
    this.bloomProgress = 0;
    this.petals = [];
    this.leaves = [];
    this.vineX = [];
    this.vineY = [];

    // Pick a little different length and bend for every vine.
    this.vineLength = random(105, 170);
    this.directionX = random(-45, 45);
    this.directionY = -this.vineLength / this.vineCount;
    this.curveAmount = random(-35, 35);

    // Randomly choose whether this stem bends once or bends left and right.
    this.multiBend = random(1) < 0.7;
    this.bendDirection = random(1) < 0.5 ? -1 : 1;
    this.bendAmount = random(14, 34);

    // Define the two handles of the smooth Bezier path.
    this.control1X =
      this.startX +
      this.directionX * 0.25 +
      this.curveAmount * 3;
    this.control1Y =
      this.startY +
      this.directionY * this.vineCount * 0.33;

    this.control2X =
      this.startX +
      this.directionX * 0.75 +
      this.curveAmount * 3;
    this.control2Y =
      this.startY +
      this.directionY * this.vineCount * 0.72;

    // Store the starting and final points of the path.
    this.vineX[0] = this.startX;
    this.vineY[0] = this.startY;
    this.vineX[this.vineCount] =
      this.startX + this.directionX + this.curveAmount;
    this.vineY[this.vineCount] =
      this.startY + this.directionY * this.vineCount;

    // Store the final point where the flower will appear.
    this.flowerX = this.vineX[this.vineCount];
    this.flowerY = this.vineY[this.vineCount];

    // Sample the stem and optionally add opposing left-right bends.
    for (this.i = 0; this.i <= this.pathSteps; this.i += 1) {
      this.pathT = this.i / this.pathSteps;
      this.drawX = bezierPoint(
        this.startX,
        this.control1X,
        this.control2X,
        this.flowerX,
        this.pathT
      );
      this.drawY = bezierPoint(
        this.startY,
        this.control1Y,
        this.control2Y,
        this.flowerY,
        this.pathT
      );

      if (this.multiBend) {
        this.drawX +=
          this.bendDirection *
          this.bendAmount *
          Math.sin(TWO_PI * this.pathT);
      }

      this.vineX[this.i] = this.drawX;
      this.vineY[this.i] = this.drawY;
    }

    // Keep the flower exactly at the end of the stem.
    this.vineX[this.pathSteps] = this.flowerX;
    this.vineY[this.pathSteps] = this.flowerY;

    // Place paired, left, or right leaves along the sampled vine path.
    for (this.i = 0; this.i < this.leafCount; this.i += 1) {
      this.pathT = (this.i + 1) / (this.leafCount + 1);
      this.segment = floor(this.pathT * this.pathSteps);
      this.segmentPart = this.pathT * this.pathSteps - this.segment;
      this.drawX = lerp(
        this.vineX[this.segment],
        this.vineX[this.segment + 1],
        this.segmentPart
      );
      this.drawY = lerp(
        this.vineY[this.segment],
        this.vineY[this.segment + 1],
        this.segmentPart
      );

      this.leafMode =
        random(1) < 0.34
          ? "pair"
          : random(1) < 0.5
            ? "left"
            : "right";
      this.leafSideCount = this.leafMode === "pair" ? 2 : 1;

      for (this.j = 0; this.j < this.leafSideCount; this.j += 1) {
        this.leaves[this.leaves.length] = {
          x: this.drawX,
          y: this.drawY,
          t: this.pathT,
          vx: random(-1.15, 1.15),
          vy: random(-0.15, 0.9),
          angle: random(-0.6, 0.6),
          spin: random(-0.05, 0.05),
          size: random(7, 12),
          side:
            this.leafMode === "pair"
              ? this.j === 0
                ? -1
                : 1
              : this.leafMode === "left"
                ? -1
                : 1,
          life: 0
        };
      }
    }
  },

  // This updates the growing stem and the drifting petals and leaves.
  update: function (objects) {
    // Find other active objects without changing their data.
    this.otherCount = 0;
    if (objects) {
      for (this.i = 0; this.i < objects.length; this.i += 1) {
        if (objects[this.i] !== this && objects[this.i].triggered > -999999) {
          this.otherCount += 1;
        }
      }
    }

    // Stop doing work after this animation has finished.
    if (this.phase === "idle" || this.phase === "done") return;

    // Measure how long this vine has been alive.
    this.now = millis();
    this.age = this.now - this.triggered;

    // Grow the stem from zero to its full path.
    if (this.phase === "grow") {
      this.vineProgress = constrain(this.age / this.growTime, 0, 1);

      // Begin the flower pop when the stem reaches its end.
      if (this.vineProgress >= 1) {
        this.phase = "bloom";
        this.bloomProgress = 0;
      }
    }

    // Open the flower quickly like a tiny colorful pop.
    if (this.phase === "bloom") {
      this.bloomProgress = constrain((this.age - this.growTime) / this.bloomTime, 0, 1);

      // Start the leaves drifting as the flower pops open.
      for (this.i = 0; this.i < this.leaves.length; this.i += 1) {
        this.leaves[this.i].x += this.leaves[this.i].vx * 0.45;
        this.leaves[this.i].y += this.leaves[this.i].vy * 0.45;
        this.leaves[this.i].vx *= 0.998;
        this.leaves[this.i].vy += 0.012;
        this.leaves[this.i].angle += this.leaves[this.i].spin;
        this.leaves[this.i].life += 0.004;
      }

      // Release the petals after the flower is fully open.
      if (this.bloomProgress >= 1) {
        this.phase = "fall";
        this.petals = [];

        // Give every petal its own angle, speed, spin, and color.
        for (this.i = 0; this.i < 8; this.i += 1) {
          this.petals[this.i] = {
            x: this.flowerX,
            y: this.flowerY,
            vx: random(-1.8, 1.8),
            vy: random(0.55, 1.7),
            angle: TWO_PI * this.i / 8 + random(-0.18, 0.18),
            spin: random(-0.045, 0.045),
            size: random(8, 14),
            life: 0,
            color: [
              random(220, 255),
              random(70, 220),
              random(90, 255)
            ]
          };
        }
      }
    }

    // Move each loose petal and leaf and slowly make them disappear.
    if (this.phase === "fall") {
      for (this.i = 0; this.i < this.petals.length; this.i += 1) {
        this.petals[this.i].x += this.petals[this.i].vx;
        this.petals[this.i].y += this.petals[this.i].vy;
        this.petals[this.i].vx *= 0.995;
        this.petals[this.i].vy *= 0.992;
        this.petals[this.i].angle += this.petals[this.i].spin;
        this.petals[this.i].life += 0.012;
      }

      for (this.i = 0; this.i < this.leaves.length; this.i += 1) {
        this.leaves[this.i].x += this.leaves[this.i].vx;
        this.leaves[this.i].y += this.leaves[this.i].vy;
        this.leaves[this.i].vx *= 0.998;
        this.leaves[this.i].vy += 0.012;
        this.leaves[this.i].angle += this.leaves[this.i].spin;
        this.leaves[this.i].life += 0.012;
      }

      // Remove the whole effect after all petals and leaves have faded.
      this.j = 0;
      for (this.i = 0; this.i < this.petals.length; this.i += 1) {
        if (this.petals[this.i].life < 1) this.j += 1;
      }
      for (this.i = 0; this.i < this.leaves.length; this.i += 1) {
        if (this.leaves[this.i].life < 1) this.j += 1;
      }
      if (this.j === 0 || this.age > this.duration) {
        this.phase = "done";
        this.triggered = -1000000;
      }
    }
  },

  // This draws the stem, flower pop, and floating petals and leaves.
  display: function (objects) {
    // Choose a clear color system before using any colors.
    colorMode(RGB, 255, 255, 255, 255);

    // Do not draw a finished animation.
    if (this.phase === "idle" || this.phase === "done") return;

    // Draw only the part of the green stem reached by the growing point.
    stroke(45, 125, 55, 235);
    strokeWeight(2.4);
    noFill();

    this.segmentPart = constrain(this.vineProgress, 0, 1);
    this.segment = floor(this.segmentPart * this.pathSteps);

    beginShape();
    for (this.i = 0; this.i <= this.segment; this.i += 1) {
      vertex(this.vineX[this.i], this.vineY[this.i]);
    }

    if (this.segment < this.pathSteps) {
      this.pathT = this.segmentPart * this.pathSteps - this.segment;
      this.drawX = lerp(
        this.vineX[this.segment],
        this.vineX[this.segment + 1],
        this.pathT
      );
      this.drawY = lerp(
        this.vineY[this.segment],
        this.vineY[this.segment + 1],
        this.pathT
      );
      vertex(this.drawX, this.drawY);
    }
    endShape();

    // Draw leaves along the vine and let them fade as they drift away.
    noStroke();
    for (this.i = 0; this.i < this.leaves.length; this.i += 1) {
      if (
        this.phase === "fall" ||
        this.phase === "bloom" ||
        this.leaves[this.i].t <= this.vineProgress
      ) {
        this.drawX = 255 * constrain(1 - this.leaves[this.i].life, 0, 1);
        push();
        translate(this.leaves[this.i].x, this.leaves[this.i].y);
        rotate(this.leaves[this.i].angle);
        scale(this.leaves[this.i].side, 1);
        fill(55, 145, 60, this.drawX);
        ellipse(
          0,
          0,
          this.leaves[this.i].size,
          this.leaves[this.i].size * 0.48
        );
        pop();
      }
    }

    // Draw the closed bud while the flower is beginning to open.
    if (this.phase === "bloom") {
      this.bloomProgress = constrain(this.bloomProgress, 0, 1);
      this.drawX = this.easeOut(this.bloomProgress);
      noStroke();
      fill(245, 180, 55, 255);
      ellipse(this.flowerX, this.flowerY, 10 + this.drawX * 9, 12 + this.drawX * 12);

      // Spread colorful petals outward as the bud pops open.
      for (this.i = 0; this.i < 8; this.i += 1) {
        push();
        translate(this.flowerX, this.flowerY);
        rotate(TWO_PI * this.i / 8 + this.drawX * 0.25);
        fill(
          220 + this.i * 4,
          75 + this.i * 15,
          125 + this.i * 10,
          245
        );
        ellipse(0, -this.drawX * 17, 8 + this.drawX * 10, 16 + this.drawX * 22);
        pop();
      }

      // Keep a bright center on top of the petals.
      fill(255, 205, 55, 255);
      ellipse(this.flowerX, this.flowerY, 9 + this.drawX * 5, 9 + this.drawX * 5);
    }

    // Draw each detached petal with its own fading transparency.
    if (this.phase === "fall") {
      noStroke();
      for (this.i = 0; this.i < this.petals.length; this.i += 1) {
        this.drawX = 1 - this.petals[this.i].life;
        push();
        translate(this.petals[this.i].x, this.petals[this.i].y);
        rotate(this.petals[this.i].angle);
        fill(
          this.petals[this.i].color[0],
          this.petals[this.i].color[1],
          this.petals[this.i].color[2],
          255 * this.drawX
        );
        ellipse(0, 0, this.petals[this.i].size, this.petals[this.i].size * 1.8);
        pop();
      }
    }
  }
}

{
  /*
  Each ball keeps its own position, velocity, color choice, age, and size variation.
  The random size range and bounce settings are adjustable through the controls.
  Colors and sizes are read while updating and drawing, so changes affect existing
  and future balls immediately.

  On mouse or touch:
  save the position
  choose the next color
  choose a size variation
  start the ball's downward motion
  record the current time

  Before drawing:
  calculate the remaining lifetime
  calculate the current rendered diameter
  apply gravity
  move the ball
  place it on the floor and reverse its velocity when it lands
  read the selected color and size
  fade the color
  draw the ball.

  The ball bounces using its current size so it remains above the floor while
  shrinking, and its animation ends when its lifetime expires.
  */
  triggered: -1000000,

  // This is how long each ball stays alive.
  duration: 1000,

  // These controls change the colors, sizes, random size range, and bounce motion.
  controlSchema: {
    redColor: {
