    blueColor: {
      type: "color",
      label: "Blue ball color",
      default: "#1e88e5"
    },
    greenColor: {
      type: "color",
      label: "Green ball color",
      default: "#43a047"
    },
    yellowColor: {
      type: "color",
      label: "Yellow ball color",
      default: "#fdd835"
