      label: "Blue ball size",
      default: 55,
      min: 10,
      max: 140,
      step: 1
    },
    greenDiameter: {
      type: "range",
      label: "Green ball size",
      default: 70,
      min: 10,
      max: 160,
      step: 1
    },
    yellowDiameter: {
      type: "range",
      label: "Yellow ball size",
      default: 45,
      min: 10,
      max: 130,
      step: 1
