    this.y = y;
    this.triggered = millis();
    this.timer = 0;
    this.lastUpdate = this.triggered;
    this.active = true;
    this.fragments = [];
    this.bunnyPositions = [];

    const maxBunnies = Math.max(1, Math.floor(
      controls && controls.maxBunnies !== undefined
        ? controls.maxBunnies
        : this.controlSchema.maxBunnies.default
    ));

    this.displayCount = Math.min(
      maxBunnies,
      Math.pow(
        2,
        (varContainer.triggerCounter - 1) % this.holdRhythm.length
      )
    );

    const count = Math.max(1, Math.floor(
      controls && controls.bunnyCount !== undefined
        ? controls.bunnyCount
        : this.controlSchema.bunnyCount.default
    ));
    const baseSize = controls && controls.bunnySize !== undefined
      ? controls.bunnySize
      : this.controlSchema.bunnySize.default;
    const spread = controls && controls.explosionSpread !== undefined
      ? controls.explosionSpread
      : this.controlSchema.explosionSpread.default;

    const areaRadius = baseSize * (0.38 + Math.sqrt(this.displayCount) * 0.2);

    for (let i = 0; i < this.displayCount; i += 1) {
      const positionAngle = random(TWO_PI);
      const positionRadius = Math.sqrt(random()) * areaRadius;

      this.bunnyPositions.push({
        x: cos(positionAngle) * positionRadius,
        y: sin(positionAngle) * positionRadius
      });
    }

    for (let i = 0; i < count; i += 1) {
      const direction = random(TWO_PI);
      const startSize = baseSize * random(0.16, 0.3);
      const outwardSpeed = random(0.7, 1.35) * spread;

      this.fragments.push({
        x: x + random(-baseSize * 0.08, baseSize * 0.08),
        y: y + random(-baseSize * 0.08, baseSize * 0.08),
        vx: cos(direction) * outwardSpeed,
        vy: sin(direction) * outwardSpeed,
        size: startSize,
        angle: random(TWO_PI),
        spin: random(-0.055, 0.055),
        age: 0
      });
    }
