  display(objects, controls) {
    if (!this.active) return;

    colorMode(RGB, 255);

    const baseSize = controls && controls.bunnySize !== undefined
      ? controls.bunnySize
      : this.controlSchema.bunnySize.default;
    const hopHeight = controls && controls.hopHeight !== undefined
      ? controls.hopHeight
      : this.controlSchema.hopHeight.default;
    const maxBunnies = Math.max(1, Math.floor(
      controls && controls.maxBunnies !== undefined
        ? controls.maxBunnies
        : this.controlSchema.maxBunnies.default
    ));

    let bigSize = baseSize;
    let bigAlpha = 255;
    let earSpread = 0;
    let bunnyY = this.y;

    if (this.timer < this.popDuration) {
      const popProgress = Math.min(1, this.timer / this.popDuration);
      const easedPop = 1 - Math.pow(1 - popProgress, 3);
      bigSize = baseSize * (0.2 + easedPop * 0.8);
      earSpread = (1 - easedPop) * baseSize * 0.04;
    } else if (this.timer < this.explosionStart) {
      const hopStart = this.popDuration + this.holdDuration;

      if (this.timer >= hopStart) {
        const hopProgress = Math.min(
          1,
          Math.max(0, (this.timer - hopStart) / this.hopDuration)
        );
        const hopArc = Math.sin(hopProgress * PI);

        bunnyY = this.y - baseSize * hopHeight * hopArc;
        bigSize = baseSize * (1 + hopArc * 0.04);
        earSpread = hopArc * baseSize * 0.025;
      }
    } else {
      const fadeProgress = Math.min(
        1,
        (this.timer - this.explosionStart) / this.fadeDuration
      );
      const easedFade = fadeProgress * fadeProgress;
      bigSize = baseSize * (1 - easedFade);
      bigAlpha = 255 * (1 - easedFade);
      earSpread = easedFade * baseSize * 0.08;
    }

    if (bigSize > 0.5 && bigAlpha > 1) {
      const visibleCount = this.timer < this.explosionStart
        ? Math.min(this.displayCount, maxBunnies, this.bunnyPositions.length)
        : 1;

      for (let i = 0; i < visibleCount; i += 1) {
        const position = this.timer < this.explosionStart
          ? this.bunnyPositions[i]
          : { x: 0, y: 0 };

        this.drawBunny(
          this.x + position.x,
          bunnyY + position.y,
          bigSize,
          0,
          bigAlpha,
          earSpread,
          controls
        );
      }
    }

    if (this.timer < this.explosionStart) return;

    const fragmentDuration = Math.max(1, this.duration - this.explosionStart);

    for (let i = 0; i < this.fragments.length; i += 1) {
      const fragment = this.fragments[i];
      const lifeAmount = Math.min(1, fragment.age / fragmentDuration);
      const currentSize = fragment.size * (1 - lifeAmount);
      const currentAlpha = 230 * (1 - lifeAmount);

      if (currentSize > 0.5 && currentAlpha > 1) {
        this.drawBunny(
          fragment.x,
          fragment.y,
          currentSize,
          fragment.angle,
          currentAlpha,
          0,
          controls
        );
      }
    }
  }
}

