    rainColor: {
      type: "color",
      label: "Rain color",
      default: "#58A9E8"
    },
    cloudSize: {
      type: "range",
      label: "Cloud size",
      default: 1,
      min: 0.6,
      max: 1.8,
      step: 0.1
    },
    dropCount: {
      type: "range",
      label: "Rain amount",
      default: 24,
      min: 6,
      max: 60,
      step: 1
