    // Draw several overlapping circles to build the fluffy cloud.
    noStroke();
    fill(cloudPaint);
    ellipse(this.cloudX - size * 48, cloudCenterY + size * 10, size * 76, size * 48);
    ellipse(this.cloudX - size * 18, cloudCenterY - size * 13, size * 92, size * 68);
    ellipse(this.cloudX + size * 18, cloudCenterY - size * 22, size * 110, size * 78);
    ellipse(this.cloudX + size * 54, cloudCenterY + size * 8, size * 76, size * 50);
    ellipse(this.cloudX, cloudCenterY + size * 15, size * 155, size * 48);

    // Make the rain color so its brightness can fade near the bottom.
    let rainBase = color(rainHex);

    // Draw each rain drop as a thin, slightly slanted line.
    strokeWeight(max(1, size * 2));
    for (let i = 0; i < this.rainDrops.length; i += 1) {
      let drop = this.rainDrops[i];
      let fade = constrain(map(drop.y, this.cloudY + size * 45, height, 255, 70), 70, 255);
      let rainPaint = color(rainBase);
      rainPaint.setAlpha(fade);
      stroke(rainPaint);
      line(drop.x, drop.y, drop.x + drop.slant, drop.y + drop.length);
    }

    // Remove the line style so the next drawing starts cleanly.
    noStroke();
  }
}

