    this.y = y;
    this.triggered = millis();
    this.timer = 0;
    this.lastUpdate = this.triggered;
    this.active = true;
    this.fragments = [];

    const count = Math.max(1, Math.floor(
      controls && controls.bunnyCount !== undefined
        ? controls.bunnyCount
        : this.controlSchema.bunnyCount.default
    ));
    const baseSize = controls && controls.bunnySize !== undefined
      ? controls.bunnySize
      : this.controlSchema.bunnySize.default;
    const spread = controls && controls.explosionSpread !== undefined
      ? controls.explosionSpread
      : this.controlSchema.explosionSpread.default;

    for (let i = 0; i < count; i += 1) {
      const direction = random(TWO_PI);
      const startSize = baseSize * random(0.16, 0.3);
      const outwardSpeed = random(0.7, 1.35) * spread;

      this.fragments.push({
        x: x + random(-baseSize * 0.08, baseSize * 0.08),
        y: y + random(-baseSize * 0.08, baseSize * 0.08),
        vx: cos(direction) * outwardSpeed,
        vy: sin(direction) * outwardSpeed,
        size: startSize,
        angle: random(TWO_PI),
        spin: random(-0.055, 0.055),
        age: 0
      });
    }
  },

  update(objects, controls) {
    if (!this.active) return;

    const now = millis();
    const frameTime = Math.min(40, Math.max(0, now - this.lastUpdate));
    this.lastUpdate = now;
    this.timer = now - this.triggered;

    const chosenSpeed = controls && controls.fragmentSpeed !== undefined
      ? controls.fragmentSpeed
      : this.controlSchema.fragmentSpeed.default;
    const explosionDelay = controls && controls.explosionDelay !== undefined
      ? controls.explosionDelay
      : this.controlSchema.explosionDelay.default;

    let anyFragmentAlive = false;
    const explosionAge = Math.max(0, this.timer - explosionDelay);
    const fragmentDuration = Math.max(1, this.duration - explosionDelay);

    if (this.timer >= explosionDelay) {
      for (let i = this.fragments.length - 1; i >= 0; i -= 1) {
        const fragment = this.fragments[i];

        fragment.x += fragment.vx * chosenSpeed * frameTime * 0.06;
        fragment.y += fragment.vy * chosenSpeed * frameTime * 0.06;
        fragment.angle += fragment.spin * frameTime;
        fragment.age = explosionAge;

        const lifeAmount = fragment.age / fragmentDuration;
        const insideCanvas =
          fragment.x > -fragment.size * 2 &&
          fragment.x < width + fragment.size * 2 &&
          fragment.y > -fragment.size * 2 &&
          fragment.y < height + fragment.size * 2;

        if (lifeAmount < 1 && insideCanvas) {
          anyFragmentAlive = true;
        } else {
          this.fragments.splice(i, 1);
        }
      }
    }

    if (this.timer >= explosionDelay + fragmentDuration && !anyFragmentAlive) {
      this.active = false;
    }
  },

  display(objects, controls) {
    if (!this.active) return;

    colorMode(RGB, 255);

    const baseSize = controls && controls.bunnySize !== undefined
      ? controls.bunnySize
      : this.controlSchema.bunnySize.default;
    const explosionDelay = controls && controls.explosionDelay !== undefined
      ? controls.explosionDelay
      : this.controlSchema.explosionDelay.default;

    let bigSize = baseSize;
    let bigAlpha = 255;
    let earSpread = 0;

    if (this.timer < this.popDuration) {
      const popProgress = Math.min(1, this.timer / this.popDuration);
      const easedPop = 1 - Math.pow(1 - popProgress, 3);
      bigSize = baseSize * (0.2 + easedPop * 0.8);
      earSpread = (1 - easedPop) * baseSize * 0.04;
    } else if (this.timer >= explosionDelay) {
      const fadeProgress = Math.min(
        1,
        (this.timer - explosionDelay) / this.fadeDuration
      );
      const easedFade = fadeProgress * fadeProgress;
      bigSize = baseSize * (1 - easedFade);
      bigAlpha = 255 * (1 - easedFade);
      earSpread = easedFade * baseSize * 0.08;
    }

    if (bigSize > 0.5 && bigAlpha > 1) {
      this.drawBunny(this.x, this.y, bigSize, 0, bigAlpha, earSpread, controls);
    }

    if (this.timer < explosionDelay) return;

    const fragmentDuration = Math.max(1, this.duration - explosionDelay);

    for (let i = 0; i < this.fragments.length; i += 1) {
      const fragment = this.fragments[i];
      const lifeAmount = Math.min(1, fragment.age / fragmentDuration);
      const currentSize = fragment.size * (1 - lifeAmount);
      const currentAlpha = 230 * (1 - lifeAmount);

      if (currentSize > 0.5 && currentAlpha > 1) {
        this.drawBunny(
          fragment.x,
          fragment.y,
          currentSize,
          fragment.angle,
          currentAlpha,
          0,
          controls
        );
      }
    }
  }
}

{
  // Adjustable ripple count controls how many expanding rings appear after impact.
  // Shape checkboxes enable or disable the star, blob, and crystal ingredient types.
  // On trigger, choose one enabled ingredient, save its position, and begin above the surface.
  // During update, fall until impact, then move and fade fragments while expanding each ripple.
  // Generate rising bubbles near the impact and remove expired elements.
  // During display, render the ingredient, ripples, fragments, and bubbles until duration ends.

  // Timestamp of last trigger (ms)
  triggered: -1000000,
  // Animation duration (ms)
  duration: 2200,

  controlSchema: {
    fallSpeed: {
      type: "range",
      label: "Fall speed",
      default: 0.22,
      min: 0.05,
      max: 0.6,
      step: 0.01
    },
    fragmentCount: {
      type: "range",
      label: "Fragment count",
      default: 6,
      min: 3,
      max: 8,
      step: 1
    },
    fragmentSpeed: {
      type: "range",
      label: "Fragment speed",
      default: 1.8,
      min: 0.5,
      max: 4,
      step: 0.1
    },
    rippleSize: {
      type: "range",
      label: "Ripple size",
      default: 90,
      min: 30,
      max: 180,
      step: 1
    },
    rippleCount: {
      type: "range",
      label: "Ripple count",
      default: 3,
      min: 1,
      max: 6,
      step: 1
    },
    bubbleSize: {
      type: "range",
      label: "Bubble size",
      default: 11,
      min: 3,
      max: 24,
      step: 1
    },
    enableStar: {
      type: "checkbox",
      label: "Enable star ingredient",
      default: true
    },
    enableBlob: {
      type: "checkbox",
      label: "Enable blob ingredient",
      default: true
    },
    enableCrystal: {
      type: "checkbox",
      label: "Enable crystal ingredient",
      default: true
    }
  },

  // Drop position and fall parameters
  dropX: 0,
  dropY: 0,
  startZ: -90,
  surfaceZ: 0,
  fallSpeed: 0.22,
  currentZ: -90,
  atSurface: false,
  impactTime: -1,

  // Ingredient properties
  ingredientType: 0,
  ingredientColor: [0,0,0],

  // Fragment properties
  fragmentCount: 0,
  fragments: [],

  // Ripple properties
  rippleRadius: 0,
  rippleAlpha: 0,
  ripples: [],

  // Bubble properties
  bubbles: [],
  lastBubbleTime: 0,

  getControlValue: function(controls, name, fallback) {
    let control = controls && controls[name];
    if (control && typeof control === "object" && "value" in control) {
      return control.value;
    }
    return control === undefined ? fallback : control;
  },

  // Pick a random enabled ingredient type and color
  pickIngredient: function(controls) {
    let enabledTypes = [];
    if (this.getControlValue(controls, "enableStar", true)) enabledTypes.push(0);
    if (this.getControlValue(controls, "enableBlob", true)) enabledTypes.push(1);
    if (this.getControlValue(controls, "enableCrystal", true)) enabledTypes.push(2);
    if (enabledTypes.length === 0) {
      enabledTypes = [0, 1, 2];
    }

    this.ingredientType = enabledTypes[floor(random(enabledTypes.length))];
    colorMode(HSB, 360, 100, 100, 255);
    let hue = random(360);
    if (this.ingredientType === 0) this.ingredientColor = [hue, 80, 90, 255];
    else if (this.ingredientType === 1) this.ingredientColor = [hue, 60, 80, 255];
    else this.ingredientColor = [hue, 100, 60, 255];

    let maximumFragments = floor(this.getControlValue(controls, "fragmentCount", 6));
    this.fragmentCount = constrain(maximumFragments, 3, 8);
  },

  // Trigger the animation at the mouse position
  trigger: function(objects, x, y, controls) {
    this.dropX = x;
    this.dropY = y;
    this.startZ = -90;
    this.currentZ = this.startZ;
    this.atSurface = false;
    this.impactTime = -1;
    this.fallSpeed = this.getControlValue(controls, "fallSpeed", 0.22);
    this.pickIngredient(controls);
    this.fragments = [];
    this.rippleRadius = 0;
    this.rippleAlpha = 0;
    this.ripples = [];
    this.bubbles = [];
    this.lastBubbleTime = millis();
    this.triggered = millis();
    if (!("triggerCounter" in varContainer)) varContainer.triggerCounter = 0;
    varContainer.triggerCounter++;
  },

  // Update the animation state
  update: function(objects, controls) {
    let t = millis() - this.triggered;
    if (t < 0 || t > this.duration) return;

    this.fallSpeed = this.getControlValue(controls, "fallSpeed", 0.22);

    // Falling phase
    if (!this.atSurface) {
      let z = this.startZ + this.fallSpeed * t * 1.5;
      if (z >= this.surfaceZ) {
        z = this.surfaceZ;
        this.atSurface = true;
        this.impactTime = millis();
        this.fragments = [];

        let angleStep = TWO_PI / this.fragmentCount;
        let fragmentSpeed = this.getControlValue(controls, "fragmentSpeed", 1.8);

        // Create fragments with outward velocities
        for (let i = 0; i < this.fragmentCount; i++) {
          let ang = angleStep * i + random(-0.3, 0.3);
          this.fragments.push({
            x: this.dropX,
            y: this.dropY,
            dx: cos(ang),
            dy: sin(ang),
            speed: fragmentSpeed,
            alpha: 255,
            t0: millis()
          });
        }

        let rippleCount = floor(this.getControlValue(controls, "rippleCount", 3));
        rippleCount = constrain(rippleCount, 1, 6);
        this.ripples = [];
        for (let i = 0; i < rippleCount; i++) {
          this.ripples.push({
            radius: 0,
            alpha: 140,
            delay: i * 85
          });
        }
        this.rippleRadius = 0;
        this.rippleAlpha = 140;
      }
      this.currentZ = z;
    } else {
      // Impact, fragment, and ripple phase
      let fragTime = millis() - this.impactTime;
      let fragmentSpeed = this.getControlValue(controls, "fragmentSpeed", 1.8);

      for (let f of this.fragments) {
        f.x += f.dx * fragmentSpeed;
        f.y += f.dy * fragmentSpeed;
        f.alpha = map(fragTime, 0, 600, 255, 0, true);
      }

      let maximumRippleSize = this.getControlValue(controls, "rippleSize", 90);
      for (let ripple of this.ripples) {
        let rippleTime = fragTime - ripple.delay;
        ripple.radius = map(rippleTime, 0, 700, 0, maximumRippleSize, true);
        ripple.alpha = map(rippleTime, 0, 700, 140, 0, true);
      }

      if (this.ripples.length > 0) {
        this.rippleRadius = this.ripples[this.ripples.length - 1].radius;
        this.rippleAlpha = this.ripples[this.ripples.length - 1].alpha;
      }
    }

    // Bubble generation and update
    let now = millis();
    if (now - this.lastBubbleTime > random(90, 210) && t < this.duration - 300) {
      let theta = random(TWO_PI);
      let rad = random(10, 70);
      let bx = this.dropX + cos(theta) * rad;
      let by = this.dropY + sin(theta) * rad;
      let bsize = random(
        this.getControlValue(controls, "bubbleSize", 11) * 0.65,
        this.getControlValue(controls, "bubbleSize", 11) * 1.35
      );
      this.bubbles.push({
        x: bx,
        y: by,
        r: bsize,
        alpha: 180,
        t0: now
      });
      this.lastBubbleTime = now;
    }

    for (let b of this.bubbles) {
      let bt = now - b.t0;
      b.y -= 0.13;
      b.alpha = map(bt, 0, 900, 180, 0, true);
    }
    this.bubbles = this.bubbles.filter(b => b.alpha > 8);
  },

  // Draw the animation
  display: function(objects, controls) {
    let t = millis() - this.triggered;
    if (t < 0 || t > this.duration) return;
    colorMode(HSB, 360, 100, 100, 255);
    noStroke();

    // Draw bubbles
    for (let b of this.bubbles) {
      fill(185, 30, 100, b.alpha);
      ellipse(b.x, b.y, b.r, b.r);
    }

    // Draw ripples
    if (this.atSurface) {
      noFill();
      stroke(180, 16, 100, 140);
      strokeWeight(4);
      for (let ripple of this.ripples) {
        if (ripple.alpha > 3) {
          stroke(180, 16, 100, ripple.alpha);
          ellipse(this.dropX, this.dropY, ripple.radius * 2, ripple.radius * 2);
        }
      }
      strokeWeight(1);
    }

    // Draw falling ingredient or fragments
    if (!this.atSurface) {
      push();
      translate(this.dropX, this.dropY);
      fill(0, 40);
      ellipse(0, 0, 32 * 2, 9 * 2);
      translate(0, this.currentZ);
      this.drawIngredientShape();
      pop();
    } else {
      for (let f of this.fragments) {
        push();
        translate(f.x, f.y);
        this.drawFragmentShape(f.alpha);
        pop();
      }
    }
  },

  // Draw the main ingredient shape (all sizes doubled)
  drawIngredientShape: function() {
    colorMode(HSB, 360, 100, 100, 255);
    stroke(0,0,100,255);
    strokeWeight(2.5);
    fill(this.ingredientColor[0], this.ingredientColor[1], this.ingredientColor[2], 255);
    if (this.ingredientType === 0) {
      // star (double size)
      this.drawStar(0,0,8*2,18*2,5);
    } else if (this.ingredientType === 1) {
      // blob (double size)
      ellipse(0,0,26*2,26*2);
      fill(this.ingredientColor[0], this.ingredientColor[1], this.ingredientColor[2]+18, 120);
      noStroke();
      ellipse(4*2,-6*2,7*2,7*2);
    } else {
      // crystal (double size)
      beginShape();
      vertex(0,-16*2);
      vertex(9*2,0);
      vertex(0,16*2);
      vertex(-9*2,0);
      endShape(CLOSE);
      fill(0,0,100,45);
      noStroke();
      ellipse(0,4*2,10*2,4*2);
    }
    strokeWeight(1);
    noStroke();
  },

  // Draw a star shape
  drawStar: function(x, y, radius1, radius2, npoints) {
    let angle = TWO_PI / npoints;
    let halfAngle = angle / 2.0;
    beginShape();
    for (let a = 0; a < TWO_PI; a += angle) {
      let sx = x + cos(a) * radius2;
      let sy = y + sin(a) * radius2;
      vertex(sx, sy);
      sx = x + cos(a + halfAngle) * radius1;
      sy = y + sin(a + halfAngle) * radius1;
      vertex(sx, sy);
    }
    endShape(CLOSE);
  },

  // Draw a fragment shape (all sizes doubled)
  drawFragmentShape: function(alpha) {
    colorMode(HSB, 360, 100, 100, 255);
    stroke(0,0,100,alpha);
    strokeWeight(1.2);
    fill(this.ingredientColor[0], this.ingredientColor[1], this.ingredientColor[2], alpha);
    if (this.ingredientType === 0) {
      ellipse(0,0,7*2,7*2);
    } else if (this.ingredientType === 1) {
      ellipse(0,0,6*2,9*2);
    } else {
      beginShape();
      vertex(0,-7*2);
      vertex(4*2,0);
      vertex(0,7*2);
      vertex(-4*2,0);
      endShape(CLOSE);
    }
    strokeWeight(1);
    noStroke();
  }
}

{
  // Key changes: fixed the object structure syntax, added a brightness control,
  // and kept all adjustable visual values synchronized with the implementation.
  // Transparency is applied through p5.Color.setAlpha() before drawing.
  // On mousePressed, trigger() saves the center and timestamp, then creates
  // randomly hued particles with adjustable count, speed, and delay.
  // update() waits, moves, slows, sparkles, and fades each particle.
  // display() reads the current visual controls and draws layered glowing stars.
  // Trigger -> save position and timestamp -> create delayed particles.
  // Update -> calculate elapsed time -> move visible particles -> sparkle -> fade.
  // Display -> read visual controls -> draw glow layers and star shapes.

  // When the firework was triggered
  triggered: -1000000,
  // How long the animation lasts (ms)
  duration: 1400,
  controlSchema: {
    particleCount: {
      type: "range",
      label: "Particle count",
      default: 28,
      min: 8,
      max: 80,
      step: 1
    },
    speed: {
      type: "range",
      label: "Particle speed",
      default: 3.5,
      min: 1,
      max: 8,
      step: 0.1
    },
    delay: {
      type: "range",
      label: "Maximum delay",
      default: 200,
      min: 0,
      max: 500,
      step: 10
    },
    sparkleSize: {
      type: "range",
      label: "Sparkle size",
      default: 4.5,
      min: 2,
      max: 8,
      step: 0.1
    },
    sparkleBrightness: {
      type: "range",
      label: "Sparkle brightness",
      default: 90,
      min: 70,
      max: 100,
      step: 1
    },
    glow: {
      type: "range",
      label: "Glow strength",
      default: 1,
      min: 0.5,
      max: 2,
      step: 0.1
    }
  },
  // Where the firework explodes
  centerX: 0,
  centerY: 0,
  // How many particles in the firework
  particleCount: 28,
  // Array to store each particle's info
  particles: [],
  readControl: function(controls, name, fallback) {
    if (controls && controls[name] !== undefined) {
      return controls[name];
    }
    return fallback;
  },
  makeColor: function(hue, brightness, alpha) {
    let particleColor = color(hue, 80, brightness);
    particleColor.setAlpha(alpha);
    return particleColor;
  },
  // Save the mouse position and time when triggered
  trigger: function(objects, x, y, controls) {
    // Save the explosion center
    this.centerX = x;
    this.centerY = y;
    // Save when the firework started
    this.triggered = millis();
    // Clear old particles
    this.particles = [];
    // Set color mode to HSB for pretty colors
    colorMode(HSB, 360, 100, 100, 255);

    let particleCount = floor(constrain(this.readControl(controls, "particleCount", this.particleCount), 1, 200));
    let speed = this.readControl(controls, "speed", 3.5);
    let maximumDelay = this.readControl(controls, "delay", 200);
    let sparkleSize = this.readControl(controls, "sparkleSize", 4.5);

    this.particleCount = particleCount;

    // Make each particle
    for (let i = 0; i < this.particleCount; i++) {
      // Angle for this particle (evenly around the circle)
      let angle = (TWO_PI * i) / this.particleCount;
      // How fast the particle moves
      let particleSpeed = random(max(0, speed * 0.6), speed * 1.4);
      // How much the particle slows down each frame
      let drag = random(0.95, 0.98);
      // How long to wait before showing this particle
      let delay = random(0, maximumDelay);
      // Color hue for this particle (random rainbow hue)
      let hue = random(0, 360);
      // Store all the info for this particle
      this.particles.push({
        angle: angle,
        speed: particleSpeed,
        drag: drag,
        delay: delay,
        x: 0,
        y: 0,
        // Used to fade out the particle
        alpha: 255,
        // Used for sparkle size
        sparkleSize: random(sparkleSize * 0.7, sparkleSize * 1.3),
        // Used for sparkle brightness
        sparkleBright: random(80, 100),
        // Particle color
        hue: hue,
        // How old is this particle (ms)
        age: 0,
        // Is this particle visible yet?
        visible: false
      });
    }
  },
  // Update all particles
  update: function(objects, controls) {
    // How much time since the firework started
    let now = millis();
    let elapsed = now - this.triggered;
    let speedScale = this.readControl(controls, "speed", 3.5) / 3.5;

    // For each particle
    for (let i = 0; i < this.particles.length; i++) {
      let p = this.particles[i];
      // Wait for the delay before showing the particle
      if (!p.visible && elapsed > p.delay) {
        p.visible = true;
        // Start the age counter
        p.age = elapsed - p.delay;
      }
      // Only update if visible
      if (p.visible) {
        // Move the particle outward
        p.x += cos(p.angle) * p.speed * speedScale;
        p.y += sin(p.angle) * p.speed * speedScale;
        // Slow down the particle
        p.speed *= p.drag;
        // Add some random jitter for sparkle
        p.x += random(-0.7, 0.7);
        p.y += random(-0.7, 0.7);
        // Age the particle
        p.age += deltaTime;
        // Fade out the alpha (slower at first, faster at end)
        let fadeStart = this.duration * 0.5;
        if (elapsed > fadeStart + p.delay) {
          let fadeAmount = map(elapsed - fadeStart - p.delay, 0, this.duration * 0.5, 0, 255);
          p.alpha = max(0, 255 - fadeAmount);
        }
        // Sparkle: randomly change brightness and size a little
        p.sparkleBright += random(-5, 5);
        p.sparkleBright = constrain(p.sparkleBright, 70, 100);
        p.sparkleSize += random(-0.4, 0.4);
        p.sparkleSize = constrain(p.sparkleSize, 2, 7);
      }
    }
  },
  // Draw all particles
  display: function(objects, controls) {
    // Set color mode for glowing colors
    colorMode(HSB, 360, 100, 100, 255);

    let sparkleScale = this.readControl(controls, "sparkleSize", 4.5) / 4.5;
    let glowScale = this.readControl(controls, "glow", 1);
    let brightnessOffset = this.readControl(controls, "sparkleBrightness", 90) - 90;

    // Draw each particle
    for (let i = 0; i < this.particles.length; i++) {
      let p = this.particles[i];
      // Only draw if visible and not fully faded
      if (p.visible && p.alpha > 0) {
        let sparkleSize = p.sparkleSize * sparkleScale;
        let sparkleBright = constrain(p.sparkleBright + brightnessOffset, 0, 100);

        // Make the glow by drawing several circles with different alpha and size
        push();
        // Move to the explosion center plus particle offset
        translate(this.centerX + p.x, this.centerY + p.y);
        noStroke();
        // Outer glow (bigger, more transparent)
        fill(this.makeColor(p.hue, 100, p.alpha * 0.12 * glowScale));
        ellipse(0, 0, sparkleSize * 4, sparkleSize * 4);
        // Middle glow
        fill(this.makeColor(p.hue, sparkleBright, p.alpha * 0.25 * glowScale));
        ellipse(0, 0, sparkleSize * 2.2, sparkleSize * 2.2);
        // Inner star (brightest)
        fill(this.makeColor(p.hue, 100, p.alpha));
        // Draw a little star shape
        this.drawStar(0, 0, sparkleSize * 0.5, sparkleSize, 5);
        pop();
      }
    }
  },
  // Helper to draw a star shape at (x, y)
  drawStar: function(x, y, radius1, radius2, npoints) {
    // Star has points sticking out
    let angle = TWO_PI / npoints;
    let halfAngle = angle / 2.0;
    beginShape();
    for (let a = 0; a < TWO_PI; a += angle) {
      let sx = x + cos(a) * radius2;
      let sy = y + sin(a) * radius2;
      vertex(sx, sy);
      sx = x + cos(a + halfAngle) * radius1;
      sy = y + sin(a + halfAngle) * radius1;
      vertex(sx, sy);
    }
    endShape(CLOSE);
  }
}

{
  /*
  Added adjustable controls for fish count, swimming speed, follow strength,
  wiggle strength, fish scale, and tail movement while keeping the existing
  HSB fish colors unchanged.
  On the first update, create the configured number of fish at random positions.
  While pressed inside the canvas, update the shared target to the pointer.
  Each frame, steer fish toward the target when active, add swimming wiggle,
  move fish, keep them inside the canvas, and advance their animation phases.
  During display, draw every fish with its animated tail and eye.
  */
  triggered: -1000000,
  duration: 4000,
  controlSchema: {
    fishCount: {
      type: "range",
      label: "Fish count",
      default: 8,
      min: 1,
      max: 20,
      step: 1
    },
    swimSpeed: {
      type: "range",
      label: "Swim speed",
      default: 1,
      min: 0.2,
      max: 3,
      step: 0.1
    },
    followStrength: {
      type: "range",
      label: "Follow strength",
      default: 0.12,
      min: 0,
      max: 0.4,
      step: 0.01
    },
    wiggleStrength: {
      type: "range",
      label: "Wiggle strength",
      default: 0.25,
      min: 0,
      max: 1,
      step: 0.01
    },
    fishScale: {
      type: "range",
      label: "Fish scale",
      default: 1,
      min: 0.5,
      max: 2,
      step: 0.1
    },
    tailWiggle: {
      type: "range",
      label: "Tail movement",
      default: 6,
      min: 0,
      max: 12,
      step: 1
    }
  },
  fishCount: 8,
  fishes: [],
  mouseTarget: { x: 0, y: 0 },
  initialized: false,
  createFish: function() {
    return {
      x: random(width),
      y: random(height),
      vx: random(-1, 1) * 0.5,
      vy: random(-1, 1) * 0.5,
      phase: random(TWO_PI)
    };
  },
  // Set the target position for fish to follow when mouse is pressed
  trigger: function(objects, x, y, controls) {
    this.triggered = millis();
    this.mouseTarget.x = x;
    this.mouseTarget.y = y;
  },
  update: function(objects, controls) {
    let now = millis();
    let fishCount = controls && controls.fishCount !== undefined ? controls.fishCount : this.fishCount;
    let swimSpeed = controls && controls.swimSpeed !== undefined ? controls.swimSpeed : 1;
    let followStrength = controls && controls.followStrength !== undefined ? controls.followStrength : 0.12;
    let wiggleStrength = controls && controls.wiggleStrength !== undefined ? controls.wiggleStrength : 0.25;

    fishCount = max(1, floor(fishCount));
    this.fishCount = fishCount;

    // Initialize fishes at random positions and velocities on first run
    if (!this.initialized) {
      this.fishes = [];
      for (let i = 0; i < fishCount; i++) {
        this.fishes.push(this.createFish());
      }
      this.initialized = true;
    } else {
      while (this.fishes.length < fishCount) {
        this.fishes.push(this.createFish());
      }
      if (this.fishes.length > fishCount) {
        this.fishes.splice(fishCount);
      }
    }

    // Check if mouse is pressed and inside the canvas
    let mouseInCanvas = mouseX >= 0 && mouseX < width && mouseY >= 0 && mouseY < height;
    let followMouse = mouseIsPressed && mouseInCanvas;
    if (followMouse) {
      this.mouseTarget.x = mouseX;
      this.mouseTarget.y = mouseY;
    }

    // Update each fish's position, velocity, and phase
    for (let i = 0; i < this.fishes.length; i++) {
      let fish = this.fishes[i];
      // Steer toward mouse if needed
      if (followMouse) {
        let dx = this.mouseTarget.x - fish.x;
        let dy = this.mouseTarget.y - fish.y;
        let distToTarget = sqrt(dx * dx + dy * dy);
        let dirX = distToTarget > 1 ? dx / distToTarget : 0;
        let dirY = distToTarget > 1 ? dy / distToTarget : 0;
        fish.vx = fish.vx * 0.92 + dirX * followStrength;
        fish.vy = fish.vy * 0.92 + dirY * followStrength;
      }
      // Add wiggle to velocity for natural swim
      let wiggleAngle = fish.phase + now * 0.005 + i;
      fish.vx += cos(wiggleAngle) * wiggleStrength * 0.04;
      fish.vy += sin(wiggleAngle) * wiggleStrength * 0.04;
      // Move fish by velocity
      fish.x += fish.vx * swimSpeed;
      fish.y += fish.vy * swimSpeed;
      // Keep fish inside canvas bounds
      if (fish.x < 0) fish.x = 0;
      if (fish.x > width) fish.x = width;
      if (fish.y < 0) fish.y = 0;
      if (fish.y > height) fish.y = height;
      // Update phase for animation
      fish.phase += 0.07 + random(-0.01, 0.01);
    }
  },
  display: function(objects, controls) {
    let now = millis();
    let fishScale = controls && controls.fishScale !== undefined ? controls.fishScale : 1;
    let tailWiggleAmount = controls && controls.tailWiggle !== undefined ? controls.tailWiggle : 6;
    colorMode(HSB, 360, 100, 100, 100);
    // Draw each fish with animated tail and eye
    for (let i = 0; i < this.fishes.length; i++) {
      let fish = this.fishes[i];
      let angle = atan2(fish.vy, fish.vx);
      let hue = (180 + i * 40) % 360;
      push();
      translate(fish.x, fish.y);
      rotate(angle);
      scale(fishScale);
      noStroke();
      fill(hue, 70, 90, 100); // Body color
      ellipse(0, 0, 32, 14);
      let tailWiggle = sin(fish.phase + now * 0.01) * tailWiggleAmount;
      fill(hue, 60, 70, 90); // Tail color
      triangle(-16, 0, -28, -8 + tailWiggle, -28, 8 + tailWiggle);
      fill(0, 0, 100, 100); // Eye white
      ellipse(9, -3, 5, 5);
      fill(0, 0, 0, 100); // Eye black
      ellipse(10, -3, 2, 2);
      pop();
    }
  }
}

{
  // Added an adjustable butterfly size control read during every display call.
  // Triggering resets the lifecycle, stores the interaction position, and randomises
  // wing details and flight direction.
  // Updating advances through caterpillar, chrysalis, emergence, and flight stages.
  // Drawing renders the active stage, scales the butterfly from its current control,
  // and applies transparent p5.Color fills correctly.
  //
  // On trigger:
  //   save the interaction position and reset animation state
  //   choose a wing palette and generate wing spot seeds
  //   randomise caterpillar movement and butterfly flight velocity
  // On update:
  //   calculate normalised animation progress
  //   update stage-specific position, opacity, wing, crack, and flight values
  // On display:
  //   render the caterpillar, cocoon, or scaled butterfly for the current stage
  //   read current visual controls and draw both wings
  controlSchema: {
    wingColor: {
      type: "color",
      label: "Wing colour",
      default: "#D2505A"
    },
    wingSpotColor: {
      type: "color",
      label: "Wing spot colour",
      default: "#D22864"
    },
    butterflySize: {
      type: "range",
      label: "Butterfly size",
      default: 1,
      min: 0.5,
      max: 2,
      step: 0.1
    }
  },
  triggered: -1000000,
  duration: 11000,
  x: 0,
  y: 0,
  butterflyLift: 0,
  wingFlap: 0,
  chrysalisColor: [120, 200, 80],
  crackGlow: 0,
  wingOpen: 0,
  hasFlown: false,
  caterpillarSegments: 7,
  wingSeeds: [],
  wingPalette: {
    main: [210, 80, 90],
    spot: [210, 40, 100]
  },
  wingPalettes: [
    { main: [210, 80, 90], spot: [210, 40, 100] },
    { main: [30, 90, 95], spot: [40, 50, 100] },
    { main: [275, 60, 85], spot: [290, 30, 100] }
  ],
  caterpillarSquirmDir: 1,
  caterpillarMoveDir: 1,
  caterpillarOffset: 0,
  butterflyFlyVelX: 0,
  butterflyFlyVelY: 0,
  cocoonFade: 1,
  butterflyFlyStartX: 0,
  butterflyFlyStartY: 0,
  butterflyFlying: false,
  trigger: function(objects, x, y, controls) {
    this.x = x;
    this.y = y;
    this.triggered = millis();
    this.butterflyLift = 0;
    this.wingFlap = 0;
    this.wingOpen = 0;
    this.hasFlown = false;
    this.cocoonFade = 1;
    this.butterflyFlying = false;
    this.butterflyFlyStartX = x;
    this.butterflyFlyStartY = y;
    let p = floor(random(this.wingPalettes.length));
    this.wingPalette = this.wingPalettes[p];
    this.wingSeeds = [];
    for (let i = 0; i < 6; i++) {
      let h = this.wingPalette.main[0] + random(-15, 15);
      let s = this.wingPalette.main[1] + random(-10, 10);
      let b = this.wingPalette.main[2] + random(-10, 10);
      this.wingSeeds.push({
        x: random(-32, 32),
        y: random(-24, 24),
        r: random(8, 18),
        h: (h + 360) % 360,
        s: constrain(s, 40, 100),
        b: constrain(b, 60, 100)
      });
    }
    this.caterpillarSquirmDir = random([1, -1]);
    this.caterpillarMoveDir = random([1, -1]);
    this.caterpillarOffset = 0;
    // Set random butterfly flight direction and speed
    let angle = random(-PI / 4, -3 * PI / 4);
    let speed = random(2.5, 4.5);
    this.butterflyFlyVelX = cos(angle) * speed;
    this.butterflyFlyVelY = sin(angle) * speed;
  },
  update: function(objects, controls) {
    let t = (millis() - this.triggered) / this.duration;
    t = constrain(t, 0, 1);
    if (t < 0.13) {
      this.wingOpen = 0;
      this.butterflyLift = 0;
      // Move caterpillar left or right slowly during its stage
      // Offset is a smooth function of t, direction, and a little squirm
      let dist = 60;
      let squirm = sin(t * PI * 6) * 8;
      this.caterpillarOffset = map(t, 0, 0.13, 0, dist * this.caterpillarMoveDir) + squirm;
      this.cocoonFade = 1;
      this.butterflyFlying = false;
      this.x = this.butterflyFlyStartX;
      this.y = this.butterflyFlyStartY;
    }
    else if (t < 0.24) {
      let p = map(t, 0.13, 0.24, 0, 1);
      this.chrysalisColor = [
        lerp(120, 70, p),
        lerp(200, 150, p),
        lerp(80, 60, p)
      ];
      this.cocoonFade = 1;
      this.butterflyFlying = false;
      this.x = this.butterflyFlyStartX;
      this.y = this.butterflyFlyStartY;
    }
    else if (t < 0.30) {
      this.cocoonFade = 1;
      this.butterflyFlying = false;
      this.x = this.butterflyFlyStartX;
      this.y = this.butterflyFlyStartY;
      // Do nothing during this waiting phase
    }
    else if (t < 0.40) {
      let p = map(t, 0.30, 0.40, 0, 1);
      this.crackGlow = sin(PI * p);
      this.cocoonFade = 1;
      this.butterflyFlying = false;
      this.x = this.butterflyFlyStartX;
      this.y = this.butterflyFlyStartY;
    }
    else if (t < 0.65) {
      this.wingOpen = t < 0.51 ? map(t, 0.40, 0.51, 0, 1) : 1;
      this.wingFlap = t < 0.51 ? 0 : sin((millis() - this.triggered - 5100) * 0.008) * 0.25;
      // Fade cocoon out between 0.51 and 0.65
      if (t < 0.51) {
        this.cocoonFade = 1;
      } else {
        this.cocoonFade = map(t, 0.51, 0.65, 1, 0);
      }
      this.butterflyFlying = false;
      this.x = this.butterflyFlyStartX;
      this.y = this.butterflyFlyStartY;
    }
    else if (t < 1.0) {
      this.wingOpen = 1;
      this.hasFlown = true;
      this.wingFlap = sin((millis() - this.triggered - 6500) * 0.012) * 0.35;
      this.butterflyLift = map(t, 0.65, 0.78, 0, 1);
      this.cocoonFade = 0;
