      if (t >= 0.78) {
        if (!this.butterflyFlying) {
          this.butterflyFlying = true;
          // Save current position as flight origin if not already set
          this.x = this.butterflyFlyStartX;
          this.y = this.butterflyFlyStartY - 28 - 80 * 1;
        }
        // Move butterfly by velocity
        this.x += this.butterflyFlyVelX;
        this.y += this.butterflyFlyVelY;
        // End animation early if butterfly is off screen
        if (
          this.x < -120 || this.x > width + 120 ||
          this.y < -120 || this.y > height + 120
        ) {
          this.triggered = -1000000;
        }
      } else {
        // Stay at spot, with lift
        this.x = this.butterflyFlyStartX;
        this.y = this.butterflyFlyStartY - 28 - 80 * this.butterflyLift;
      }
    }
  },
  display: function(objects, controls) {
    colorMode(HSB, 360, 100, 100, 1);
    let t = (millis() - this.triggered) / this.duration;
    t = constrain(t, 0, 1);
    let cx = this.x;
    let cy = this.y;
    if (t < 0.13) {
      let curl = map(t, 0, 0.13, 0, PI * 0.9) * this.caterpillarSquirmDir;
      let faceAlpha = map(t, 0, 0.13, 1, 0.1);
      for (let i = 0; i < this.caterpillarSegments; i++) {
        let ang = curl * (i / (this.caterpillarSegments - 1));
        let segX = cx + this.caterpillarOffset + cos(ang) * (i * 22 - 66);
        let segY = cy - sin(ang) * (i * 8);
        fill(120, 80, 70, 1);
        noStroke();
        ellipse(segX, segY, 36, 28);
        if (i === 0) {
          fill(120, 90, 55, faceAlpha);
          ellipse(segX, segY, 38, 30);
          fill(0, 0, 0, faceAlpha);
          ellipse(segX - 8, segY - 6, 5, 5);
          ellipse(segX + 8, segY - 6, 5, 5);
          noFill();
          stroke(0, 0, 0, faceAlpha);
          strokeWeight(2);
          arc(segX, segY + 4, 14, 8, 0, PI);
          stroke(120, 90, 55, faceAlpha);
          strokeWeight(2);
          line(segX - 10, segY - 14, segX - 18, segY - 26);
          line(segX + 10, segY - 14, segX + 18, segY - 26);
        }
        stroke(120, 60, 30, 0.7);
        strokeWeight(3);
        let legY = segY + 16;
        line(segX - 8, legY, segX - 18, legY + 8);
        line(segX + 8, legY, segX + 18, legY + 8);
      }
    }
    // Draw chrysalis/cocoon if not fully faded
    if (t >= 0.13 && this.cocoonFade > 0.01) {
      let cc = this.chrysalisColor;
      let ovalW = 48;
      let ovalH = 70;
      let cocoonAlpha = this.cocoonFade;
      fill(cc[0], cc[1], cc[2], cocoonAlpha);
      stroke(cc[0] - 10, cc[1], cc[2] - 20, 0.5 * cocoonAlpha);
      strokeWeight(3);
      ellipse(cx, cy - 10, ovalW, ovalH);
      stroke(cc[0] - 15, cc[1] - 30, cc[2] - 15, 0.2 * cocoonAlpha);
      strokeWeight(1);
      for (let i = -2; i <= 2; i++) {
        let y = cy - 10 + i * 10;
        arc(cx, y, ovalW - 8, 18, PI, 0);
      }
      // Crack glow if in correct stage
      if (t > 0.30 && t < 0.51) {
        let glow = this.crackGlow;
        stroke(60, 10, 100, (0.5 + 0.5 * glow) * cocoonAlpha);
        strokeWeight(2 + 3 * glow);
        let crackCount = 3;
        for (let i = 0; i < crackCount; i++) {
          let ang = map(i, 0, crackCount - 1, -PI / 4, PI / 4);
          let x1 = cx + cos(ang) * 14;
          let y1 = cy - 28 + sin(ang) * 8;
          let x2 = cx + cos(ang) * 18;
          let y2 = cy - 4 + sin(ang) * 12;
          line(x1, y1, x2, y2);
        }
        noStroke();
        fill(60, 10, 100, 0.15 * glow * cocoonAlpha);
        ellipse(cx, cy - 18, 36 + 24 * glow, 28 + 18 * glow);
      }
      // Face in cocoon if in correct stage
      if (t >= 0.13 && t < 0.24) {
        let faceAlpha = map(t, 0.13, 0.24, 0.8, 0) * cocoonAlpha;
        if (faceAlpha > 0.05) {
          fill(120, 90, 55, faceAlpha);
          ellipse(cx, cy + 14, 22, 16);
        }
      }
    }
    if (t >= 0.40) {
      // Butterfly emerges and stays at cocoon spot, with wings opening/flapping, or flies away
      let drawY = cy;
      let butterflySize = controls && controls.butterflySize !== undefined ? controls.butterflySize : 1;
      push();
      translate(cx, drawY);
      scale(butterflySize);
      fill(35, 60, 40, 1);
      stroke(30, 50, 30, 1);
      strokeWeight(3);
      rect(-5, 0, 10, 48, 8);
      stroke(35, 60, 40, 1);
      strokeWeight(2);
      let antLen = t < 0.65 ? (18 + 8 * this.wingOpen) : 26;
      line(0, 0, -10, -antLen);
      line(0, 0, 10, -antLen);
      this.drawWings(0, t < 0.65 ? 18 : 24, this.wingOpen, this.wingFlap, this.wingSeeds, controls);
      pop();
    }
    colorMode(RGB, 255, 255, 255, 1);
  },
  drawWings: function(cx, cy, open, flap, seeds, controls) {
    push();
    translate(cx, cy);
    // Left wing
    push();
    let leftAngle = -PI / 2 + open * PI / 3 + flap;
    rotate(leftAngle);
    this.drawWingShape(-1, open, flap, seeds, controls);
    pop();
    // Right wing
    push();
    let rightAngle = PI / 2 - open * PI / 3 - flap;
    rotate(rightAngle);
    this.drawWingShape(1, open, flap, seeds, controls);
    pop();
    pop();
  },
  drawWingShape: function(side, open, flap, seeds, controls) {
    let wingColor = controls && controls.wingColor ? controls.wingColor : "#D2505A";
    let spotColor = controls && controls.wingSpotColor ? controls.wingSpotColor : "#D22864";
    let wingFill = color(wingColor);
    wingFill.setAlpha(1);
    let wingSpotFill = color(spotColor);
    wingSpotFill.setAlpha(0.3);
    noStroke();
    // Top (larger) oval
    push();
    rotate(radians(-18 * side));
    fill(wingFill);
    beginShape();
    vertex(0, 0);
    bezierVertex(42 * side, -22, 68 * side, -56, 32 * side, -94 * open);
    bezierVertex(8 * side, -110 * open, -18 * side, -56, -14 * side, -12);
    endShape(CLOSE);
    pop();
    // Bottom (smaller) oval, now follows the top oval's open/flap but with smaller degree
    let bottomOpen = open * 0.8;
    let bottomFlap = flap * 0.8;
    push();
    rotate(radians(22 * side));
    fill(wingFill);
    beginShape();
    vertex(0, 0);
    bezierVertex(30 * side, 10, 50 * side, 34, 22 * side, 54 * bottomOpen + 12 * bottomFlap);
    bezierVertex(6 * side, 62 * bottomOpen + 16 * bottomFlap, -12 * side, 34, -8 * side, 6);
    endShape(CLOSE);
    pop();
    // Draw spots fully overlapping the wings (on top of both ovals)
    fill(wingSpotFill);
    for (let i = 0; i < seeds.length; i++) {
      let s = seeds[i];
      // Spots distributed within the bounding box of the wing shapes
      let wx = s.x * side * open * 0.85;
      let wy = s.y * open;
      ellipse(wx, wy, s.r, s.r);
    }
  }
}
